/**
 * Fallback image-module declarations for static asset imports (e.g.
 * `import logo from "./logo.jpg"`).
 *
 * The primary declarations come from the generated `next-env.d.ts` via
 * `next/image-types/global`, but that file is untracked and regenerated by
 * Next.js — if its image-types reference is ever missing, `tsc` fails with
 * TS2307 on every image import. These tracked declarations keep typecheck
 * green in that case.
 *
 * The union shape matches reality: Vite/vitest resolves an image import to
 * a URL string while Next.js resolves it to an image object, so callers
 * keep narrowing with `typeof value === "string"`.
 */
declare module "*.jpg" {
  const content: string | { readonly src: string };
  export default content;
}

declare module "*.jpeg" {
  const content: string | { readonly src: string };
  export default content;
}
